# -------------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#define TILE_M 32
#define TILE_N 32
#define TILE_K 32

// A, B, C are stored in row‑major order.
// All tensors are half (fp16). Accumulation is performed in float.
__global__ void batched_gemm_fp16(const half *__restrict__ A,
                                  const half *__restrict__ B,
                                  half *__restrict__ C,
                                  int batch,
                                  int M,
                                  int K,
                                  int N) {
    // batch index
    const int b = blockIdx.z;
    const half *Ab = A + b * M * K;
    const half *Bb = B + b * K * N;
    half *Cb = C + b * M * N;

    // thread coordinates inside a tile
    const int tx = threadIdx.x;  // column inside tile
    const int ty = threadIdx.y;  // row inside tile

    // global row / column this thread is responsible for
    const int row = blockIdx.y * TILE_M + ty;
    const int col = blockIdx.x * TILE_N + tx;

    // shared memory tiles
    __shared__ half As[TILE_M][TILE_K];
    __shared__ half Bs[TILE_K][TILE_N];

    float acc = 0.0f;

    // loop over K dimension in tiles
    const int numTilesK = (K + TILE_K - 1) / TILE_K;
    for (int t = 0; t < numTilesK; ++t) {
        // load a tile of A
        const int aRow = row;
        const int aCol = t * TILE_K + tx;
        if (aRow < M && aCol < K) {
            As[ty][tx] = Ab[aRow * K + aCol];
        } else {
            As[ty][tx] = __float2half(0.0f);
        }

        // load a tile of B
        const int bRow = t * TILE_K + ty;
        const int bCol = col;
        if (bRow < K && bCol < N) {
            Bs[ty][tx] = Bb[bRow * N + bCol];
        } else {
            Bs[ty][tx] = __float2half(0.0f);
        }

        __syncthreads();

        // compute partial dot product
        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            acc += __half2float(As[ty][k]) * __half2float(Bs[k][tx]);
        }

        __syncthreads();
    }

    // write result
    if (row < M && col < N) {
        Cb[row * N + col] = __float2half(acc);
    }
}
'''

# Compile the kernel inline
batched_gemm = load_inline(
    name='batched_gemm_fp16',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['batched_gemm_fp16'],
    verbose=False,
)

