    """
    Drop‑in replacement for torch.nn.Module performing batched matrix multiplication
    on fp16 tensors using a custom CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "inputs must be CUDA tensors"
        assert A.dtype == torch.float16 and B.dtype == torch.float16, "inputs must be fp16"
        batch, m, k = A.shape
        _, k2, n = B.shape
        assert k == k2, "inner dimensions must match"

        # Ensure contiguous layout for pointer arithmetic
        A = A.contiguous()
        B = B.contiguous()

        C = torch.empty(batch, m, n, dtype=torch.float16, device=A.device)

        # launch configuration
        threads_per_block = (32, 32)               # (tx, ty)
        blocks_per_grid = (
            (n + 31) // 32,    # grid.x over N
            (m + 31) // 32,    # grid.y over M
            batch               # grid.z over batch dimension
        )

        stream = torch.cuda.current_stream().cuda_stream

        batched_gemm.batched_gemm_fp16(
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            batch,
            m,
            k,
            n,
            grid=blocks_per_grid,
            block=threads_per_block,
            stream=stream,
        )
        return C

